public static String convertDatesToWeekdays(String date) {
    try {
        String[] parts = date.split(" ");
        if (parts.length != 3) {
            throw new IllegalArgumentException("Date format must be 'MM dd yyyy'");
        }

        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        if (month < 1 || month > 12) {
            throw new IllegalArgumentException("Month must be between 1 and 12");
        }

        String[] months = {"January", "February", "March", "April", "May", "June",
                          "July", "August", "September", "October", "November", "December"};

        // Leap year check
        boolean isLeapYear = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
        int[] daysInMonth = {31, isLeapYear ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

        if (day < 1 || day > daysInMonth[month - 1]) {
            throw new IllegalArgumentException("Invalid day for the given month and year");
        }

        // Zeller's Congruence Algorithm to find the day of the week
        int zMonth = (month <= 2) ? month + 12 : month;
        int zYear = (month <= 2) ? year - 1 : year;
        int k = zYear % 100;
        int j = zYear / 100;

        int f = day + (13 * (zMonth + 1)) / 5 + k + k / 4 + j / 4 + 5 * j;
        int dayOfWeek = ((f % 7) + 5) % 7; // Adjusting to 0=Saturday, 1=Sunday, ..., 6=Friday

        String[] weekdays = {"Saturday", "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday"};

        return months[month - 1] + " " + day + ", " + year + " is a " + weekdays[dayOfWeek];

    } catch (NumberFormatException e) {
        return "Invalid date format";
    } catch (IllegalArgumentException e) {
        return e.getMessage();
    }
}

public static String convertDatesToWeekdays(String date) {
    try {
        String[] parts = date.split(" ");
        if (parts.length != 3) {
            throw new IllegalArgumentException("Date format must be 'MM dd yyyy'");
        }

        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        String[] months = {"January", "February", "March", "April", "May", "June",
                            "July", "August", "September", "October", "November", "December"};
        if (month < 1 || month > 12) {
            throw new IllegalArgumentException("Month must be between 1 and 12");
        }
        String monthName = months[month - 1];

        if (day < 1 || day > 31) {
            throw new IllegalArgumentException("Day must be between 1 and 31");
        }

        // Adjust month and day for Zeller's Congruence algorithm
        if (month < 3) {
            month += 12;
            year -= 1;
        }

        int k = year % 100;
        int j = year / 100;
        int h = (day + 13 * (month + 1) / 5 + k + k / 4 + j / 4 + 5 * j) % 7;

        // Zeller's Congruence returns 0 = Saturday, 1 = Sunday, ..., 6 = Friday
        String[] weekdays = {"Saturday", "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday"};
        String weekday = weekdays[h];

        return monthName + " " + day + ", " + year + " is a " + weekday;

    } catch (NumberFormatException e) {
        return "Invalid date format or numbers";
    } catch (IllegalArgumentException e) {
        return e.getMessage();
    }
}

