public double trimMean(int[] arr) {
    if (arr == null || arr.length < 20) {
        throw new IllegalArgumentException("Array must contain at least 20 elements.");
    }

    java.util.Arrays.sort(arr);
    int n = arr.length;
    int trimSize = n / 20;
    int sum = 0;

    for (int i = trimSize; i < n - trimSize; i++) {
        sum += arr[i];
    }

    return (double) sum / (n - 2 * trimSize);
}

public double trimMean(int[] arr) {
