            for (int k = 0; k <= sum; k++) {
                dp[i][j][k] = dp[i - 1][j][k];
                if (k >= nums[i - 1]) {
                    dp[i][j][k] |= dp[i - 1][j - 1][k - nums[i - 1]];
                }
            }
        }
    }

    for (int j = 1; j <= n / 2; j++) {
        if (sum * j % n == 0 && dp[n][j][sum * j / n]) {
            return true;
        }
    }

    return false;
}

