    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);
        codes.add(substring);
    }

    return codes.size() == (1 << k);
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k < 0 || k > s.length()) {
        return false;
    }

    Set<String> set = new HashSet<>();
    int needed = 1 << k; // 2^k possible binary strings of length k

    for (int i = 0; i <= s.length() - k; i++) {
        String sub = s.substring(i, i + k);
        if (set.add(sub)) { // add returns false if the set already contains the element
            needed--;
            if (needed == 0) {
                return true;
            }
        }
    }

    return false;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k < 0 || k > s.length()) {
        return false;
    }

    int totalSubstrings = 1 << k; // 2^k
    boolean[] seen = new boolean[totalSubstrings];

    for (int i = 0; i <= s.length() - k; i++) {
        int index = 0;
        for (int j = 0; j < k; j++) {
            index = (index << 1) + (s.charAt(i + j) - '0');
        }
        seen[index] = true;
    }

    for (boolean exists : seen) {
        if (!exists) {
            return false;
        }
    }

    return true;
}

