public int minInsertions(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }

    int left = 0; // To keep track of unmatched '('
    int right = 0; // To keep track of the number of insertions needed

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (right % 2 == 1) {
                // If there's an odd number of unmatched ')', we need to insert a '('
                left++;
                right--;
            }
            left++;
        } else if (c == ')') {
            right++;
            if (right == 2 && left > 0) {
                // If we have two ')' and there's a matching '(', reduce them
                left--;
                right--;
            }
        }
    }

    // The total insertions needed is the number of unmatched '(' and ')'
    return left + right;
}

public int minInsertions(String s) {
    int insertions = 0;
    int balance = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            balance--;
            if (balance == -1) {
                insertions++; // Need to insert a '('
                balance = 0;
            }
        }
    }

    // If there are leftover '(' that need balance, we need to insert ')'
    insertions += balance;
    return insertions;
}

public int minInsertions(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }

    int leftBalance = 0; // Tracks the number of unmatched '('
    int insertions = 0;  // Tracks the number of insertions needed

    for (char c : s.toCharArray()) {
        if (c == '(') {
            leftBalance++;
        } else if (c == ')') {
            if (leftBalance > 0) {
                leftBalance--;
            } else {
                insertions++; // Need to insert a matching '('
            }
        }
    }

    // After processing all characters, insertions are needed for each unmatched '('
    insertions += leftBalance * 2;

    return insertions;
}

public int minInsertions(String s) {
    int openCount = 0;
    int insertions = 0;
    int i = 0;

    while (i < s.length()) {
        if (s.charAt(i) == '(') {
            openCount++;
            i++;
        } else {
            // When we encounter a ')'
            if (openCount > 0) {
                openCount--;
            } else {
                insertions++;
            }
            // Check for the next character if it's also a ')'
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i += 2;
            } else {
                insertions++; // Need to insert a ')' to balance
                i++;
            }
        }
    }

    // Add remaining open parentheses
    insertions += openCount;
    return insertions;
}

