        } else if (c == ')') {
            if (openNeeded > 0) {
                openNeeded--; // This ')' matches with a previous '('
            } else {
                closeNeeded++; // No matching '(', need to insert a '('
            }
        }
    }

    // After the loop, openNeeded will be the number of unmatched '('
    // closeNeeded will be the number of unmatched ')'
    return openNeeded + closeNeeded;
}

