public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }

    // Generate Fibonacci numbers until the largest number less than or equal to k
    int a = 1, b = 1;
    while (b <= k) {
        int next = a + b;
        a = b;
        b = next;
    }

    // a is the largest Fibonacci number less than or equal to k
    return 1 + findMinFibonacciNumbers(k - a);
}

