public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int longest = 0;

    // Arrays to store the length of 1s in different directions
    int[][] horizontal = new int[m][n];
    int[][] vertical = new int[m][n];
    int[][] diagonal = new int[m][n];
    int[][] antiDiagonal = new int[m][n];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Horizontal
                horizontal[i][j] = (j > 0) ? horizontal[i][j - 1] + 1 : 1;
                // Vertical
                vertical[i][j] = (i > 0) ? vertical[i - 1][j] + 1 : 1;
                // Diagonal
                diagonal[i][j] = (i > 0 && j > 0) ? diagonal[i - 1][j - 1] + 1 : 1;
                // Anti-diagonal
                antiDiagonal[i][j] = (i > 0 && j < n - 1) ? antiDiagonal[i - 1][j + 1] + 1 : 1;

                // Update the longest line found
                longest = Math.max(longest, Math.max(horizontal[i][j], vertical[i][j]));
                longest = Math.max(longest, Math.max(diagonal[i][j], antiDiagonal[i][j]));
            }
        }
    }

    return longest;
}

