    int maxLength = 0;

    // Horizontal and vertical
    for (int i = 0; i < m; i++) {
        int horizontalCount = 0;
        int verticalCount = 0;
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horizontalCount++;
                maxLength = Math.max(maxLength, horizontalCount);
            } else {
                horizontalCount = 0;
            }

            if (mat[j][i] == 1) {
                verticalCount++;
                maxLength = Math.max(maxLength, verticalCount);
            } else {
                verticalCount = 0;
            }
        }
    }

    // Diagonal
    for (int k = -m + 1; k <= n - 1; k++) {
        int diagonalCount = 0;
        for (int i = Math.max(0, k); i < Math.min(m, k + n); i++) {
            int j = i - k;
            if (mat[i][j] == 1) {
                diagonalCount++;
                maxLength = Math.max(maxLength, diagonalCount);
            } else {
                diagonalCount = 0;
            }
        }
    }

    // Anti-diagonal
    for (int k = 0; k <= m + n - 2; k++) {
        int antiDiagonalCount = 0;
        for (int i = Math.max(0, k - n + 1); i < Math.min(m, k + 1); i++) {
            int j = k - i;
            if (mat[i][j] == 1) {
                antiDiagonalCount++;
                maxLength = Math.max(maxLength, antiDiagonalCount);
            } else {
                antiDiagonalCount = 0;
            }
        }
    }

    return maxLength;
}

public static String addThousandSeparator(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer.");
    }
    StringBuilder result = new StringBuilder();
    String numberStr = Integer.toString(n);
    int length = numberStr.length();

    for (int i = 0; i < length; i++) {
        result.append(numberStr.charAt(i));
        // Add separator if this digit is not the last one and it's a third digit from the end
        if (i < length - 1 && (length - i - 1) % 3 == 0) {
            result.append('.');
        }
    }

    return result.toString();
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    StringBuilder result = new StringBuilder();
    int count = 0;

    while (n > 0) {
        if (count == 3) {
            result.append('.');
            count = 0;
        }
        result.append(n % 10);
        n /= 10;
        count++;
    }

    return result.reverse().toString();
}

