public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int length = digits.length;

    // Step 1: Find the rightmost digit that is smaller than the digit next to it
    int i = length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, return -1
    if (i == -1) {
        return -1;
    }

    // Step 2: Find the smallest digit on the right side of (i-th digit) that is greater than digits[i]
    int j = length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Step 3: Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Step 4: Sort the digits after (i-th digit)
    java.util.Arrays.sort(digits, i + 1, length);

    // Convert the char array back to an integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1; // In case of overflow
    }
}

