public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Step 1: Find the first digit that is smaller than its next digit
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, return -1
    if (i == -1) {
        return -1;
    }

    // Step 2: Find the smallest digit on the right side of (i-th digit) which is greater than digits[i]
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Step 3: Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Step 4: Sort the digits after i-th position in ascending order
    java.util.Arrays.sort(digits, i + 1, len);

    // Return the new number formed
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1;
    }
}

