public static int calculateUniqueSum(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }

    int[] count = new int[1001]; // Assuming the numbers are non-negative and not larger than 1000
    int sum = 0;

    for (int num : nums) {
        if (num < 0 || num > 1000) {
            throw new IllegalArgumentException("Array elements must be between 0 and 1000");
        }
        count[num]++;
    }

    for (int i = 0; i < count.length; i++) {
        if (count[i] == 1) {
            sum += i;
        }
    }

    return sum;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }

    java.util.Map<Integer, Integer> frequencyMap = new java.util.HashMap<>();

    for (int num : nums) {
        frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
    }

    int uniqueSum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
        if (entry.getValue() == 1) {
            uniqueSum += entry.getKey();
        }
    }

    return uniqueSum;
}

